def adjacency(n: int, rel: Relation) -> List[List[int]]:
    return [[1 if rel(x, y) else 0 for y in range(n)] for x in range(n)]

def mat_mul(a, b):
    n, m, k = len(a), len(b[0]), len(b)
    return [[sum(a[i][t]*b[t][j] for t in range(k)) for j in range(m)] for i in range(n)]

def is_regular(n: int, rel: Relation) -> Tuple[bool, int]:
    degs = {sum(1 for y in range(n) if rel(x, y)) for x in range(n)}
    return (True, degs.pop()) if len(degs) == 1 else (False, -1)

def circulant(n: int, steps) -> Relation:
    S = {s % n for s in steps}
    return lambda x, y: ((y - x) % n) in S

