function VERIFY_MPF(A_R, A_S, A_U):
    n <- number of rows
    for x in 0..n-1:
        for z in 0..n-1:
            count <- 0
            for y in 0..n-1:
                count <- count + A_R[x][y] * A_S[y][z]
            if count != A_U[x][z]:
                return FALSE      # entry mismatch: not an MPF
    return TRUE                    # all entries agree: MPF holds

