from typing import List

Matrix = List[List[int]]

def verify_mpf(a_r: Matrix, a_s: Matrix, a_u: Matrix) -> bool:
    """Return True iff a_r @ a_s == a_u (a matrix product factorization)."""
    n = len(a_r)
    for x in range(n):
        for z in range(n):
            count = sum(a_r[x][y] * a_s[y][z] for y in range(n))
            if count != a_u[x][z]:
                return False
    return True

