from typing import List, Optional

Matrix = List[List[int]]

def constant_rowsum(a: Matrix) -> Optional[int]:
    """Return the common row sum (valency) if constant, else None."""
    sums = {sum(row) for row in a}
    return sums.pop() if len(sums) == 1 else None

def valency_filter(a_r: Matrix, a_s: Matrix, a_u: Matrix) -> bool:
    """Fast necessary test for an MPF: regular and u == r * s."""
    r, s, u = constant_rowsum(a_r), constant_rowsum(a_s), constant_rowsum(a_u)
    if r is None or s is None or u is None:
        return False
    return u == r * s

