    return [[sum(a[i][t] * b[t][j] for t in range(k)) for j in range(m)]
            for i in range(n)]

def circulant(n: int, steps: Tuple[int, ...]) -> Relation:
    S = {s % n for s in steps}
    return lambda x, y: ((y - x) % n) in S

def search_complement_mpf(n: int) -> List[Tuple[int, int]]:
    jmi = adjacency(n, lambda x, y: x != y)
    hits: List[Tuple[int, int]] = []
    for d1 in range(1, n // 2 + 1):
        for d2 in range(1, n // 2 + 1):
            a1 = adjacency(n, circulant(n, (d1, -d1)))
            a2 = adjacency(n, circulant(n, (d2, -d2)))
            if mat_mul(a1, a2) == jmi:
                hits.append((d1, d2))
    return hits

